        "passage": "某海岸有不同高程的海階,如圖18的 T₀ 至 T₃ 所示。海階常有海蝕凹壁。小莉推論海蝕凹壁為當地堅硬的火成岩壁受潮水長期侵蝕而成。海蝕凹壁上常有大量的穿孔貝附著在凹壁上。穿孔貝僅在潮起潮落之間的高度存活,無法長期離開水面。因此,小莉推論此海階上的海蝕凹壁主要由大地震所造成的垂直抬升而成。小莉詳細丈量每個海階和海蝕凹壁的高程,並利用凹壁上穿孔貝的碳進行碳-14定年分析。所得的結果如表3所示。\n[圖18示意(非官方文字):海岸剖面圖,橫軸為水平距離(m,0至100以上),縱軸為高程(m,0至20);主體為火成岩,海岸由海面(T₀)向陸側呈階梯狀逐級升高,T₀、T₁、T₂、T₃ 各為一級海階,各海階後方陡壁上標有海蝕凹壁,部分表面覆有沉積物。]\n表3\n階地 | 累積高程(m) | 定年結果(年)\nT₀ | 0 | 0\nT₁ | 6 | 800\nT₂ | 10 | 1600\nT₃ | 18 | 2400",
