        "question": "靜態模式時,線圈電流 I 與磁鐵之間的作用力量值為 F_B = f_B·I。由於缺乏檢測 f_B 的設備,無法從靜態模式求得待測物的質量 M。但可知,當線圈相對於磁鐵移動的速度為 v 時,線圈的感應電動勢(電壓)為 V = f_B·v,動態模式與靜態模式的 f_B 相同,示意如圖 27。分析線圈速度 v,以及對應的電壓表讀數 V,其數據如表 5,並繪製感應電壓對線圈速度(V-v)的關係圖,如圖 28 所示,藉以推算 f_B 值。當天平達靜態平衡時,線圈電流為 I = 40 mA,試以 kg 為單位,計算待測物的質量 M,須寫出計算步驟,並四捨五入至小數第 1 位。(4分)(已知重力加速度量值 g = 9.8 m/s²)\n表 5\n線圈速度 v (mm/s) | −3.8 | −2.2 | 0.1 | 1.8 | 3.6\n感應電壓 V (mV)   | −95  | −55  | 2.5 | 45  | 90\n[圖27示意(非官方文字):一個線圈與電壓表 V 相連,線圈下方為固定磁鐵(上為 N 極、下為 S 極),線圈旁以雙向箭頭表示線圈可相對磁鐵上下移動。]\n[圖28示意(非官方文字):V-v 關係圖,橫軸為線圈速度 v(mm/s,-4 至 4),縱軸為感應電壓 V(mV,-100 至 100);表5的五個數據點大致落在一條通過原點、由左下向右上的直線(虛線)上。]",
        "explanation": "(111學測自然第60題,非選擇題,4分)參考答案:(1)由動態模式求出斜率 f_B = ΔV/Δv = (90 − (−95)) / (3.6 − (−3.8)) = 25 (V·s/m);(2)由於動態模式與靜態模式的 f_B 相同,F_B = f_B·I = (ΔV/Δv) × I = 25 × 0.04 = 1.0 (N);(3)靜態平衡時,F_B = Mg,1.0 = M × 9.8 (N);(4)M = 1.0/9.8 ≈ 0.1 (kg)。評分原則(各1分):寫出 f_B = ΔV/Δv(可由表5的兩組數據計算,亦可由圖28的直線斜率決定),得1分;將所求出的 f_B 代入 F_B = f_B·I,得1分;寫出 F_B = Mg,得1分;求出正確答案 M ≈ 0.1 (kg),得1分。"
