        "passage": "煤主要作為燃料,在2020年提供了全球超過1/3的電力,但煤的使用會破壞環境,是造成氣候變化最大的人為二氧化碳(CO₂)來源。為了實現巴黎協定將全球暖化控制在2℃以下的目標,從2020年到2030年,煤的使用量需要減半。利用水力以取代燃煤來發電,是很多國家降低CO₂排放量所採取的對策之一。\n假設你被要求提出一個水力發電廠的規畫案,目標是要使它一年可達成的CO₂減排量 M 為10⁹ kg。已知水庫供水與下游水道排水都無問題,每部發電機提供電能的功率設定為 P₁ = 10⁹ W,水庫水面與發電機進水口的水位落差為 h = 100 m;當水庫的水在到達發電機進水口時,每單位質量所具有的動能為 u_w。表5列出的甲~己(括弧內為其符號)為規劃時需要考慮的一些參數。\n表 5\n甲(c₁):燃煤發電時每單位電能耗用的煤質量\n乙(c₂):每單位質量的煤發電時排放的CO₂質量\n丙(μ):每單位時間流入發電機的水質量\n丁(ε):發電機將水力轉為電力的效率\n戊(T):每部發電機每日發電的平均時間\n己(N):安裝的發電機數目",
