        "passage": "自工業革命於1760年在英國開始後,人類對於化石燃料(煤和石油)的使用滿足了經濟發展和產業革命的需求,然而這些化石燃料的燃燒,也使空氣中的二氧化碳節節上升,如圖15(a)所示。除了二氧化碳之外,人類對化石燃料的運用也在環境中留下許多痕跡,鉛元素便是其中一個例子。圖15(b)是英國某湖泊岩心(岩芯)中1700年以來的鉛濃度變化,圖15(c)則是1700年以來,該岩心中的鉛-206與鉛-207的比例(²⁰⁶Pb/²⁰⁷Pb)變化。煤和石油有著不同的鉛同位素訊號,如英國地區煤的 ²⁰⁶Pb/²⁰⁷Pb 比例為1.186,石油的 ²⁰⁶Pb/²⁰⁷Pb 比例為1.067,分析岩心中鉛濃度以及鉛同位素比例,便能推測該地過去化石燃料的使用情形。鉛-206及鉛-207是鉛元素常見的穩定同位素,來源可能是岩石、地下水、煤或石油,同時也可能從鈾元素衰變而來。鈾-238具有天然放射性,其質子數為92,中子數為146,會歷經衰變過程,轉變成穩定的鉛-206原子,如下式(2)所示。\n²³⁸₉₂U → ²³⁴₉₀Th → ²³⁴₉₁Pa → ²³⁴₉₂U → … → ²⁰⁶₈₁Tl → ²⁰⁶₈₂Pb  式(2)\n[圖15示意(非官方文字):三幅並排的圖,共用縱軸「年代(西元)」,由下往上為 1700 至 2000 年。(a) 大氣中 CO₂ 濃度(ppm,橫軸 250 至 400)為一條曲線:1700 至約 1780 年約 278 ppm,約 1780 至 1850 年約 280~285 ppm,之後逐漸上升,1900 年前後約 295~300 ppm、1950 年約 310~315 ppm,1950 年後上升加快,約 1985 年約 350 ppm,約 2010 年達 400 ppm。(b) 岩心中 Pb 濃度(ppm,橫軸 0 至 400)為一條曲線:1700 至約 1920 年大致在 50~100 ppm 之間、略有起伏(約 1800 年有一小峰約 100 ppm);約 1920 年起明顯上升,1930 至 1960 年約 200 ppm,約 1965 至 1970 年升到最高約 330 ppm,約 1985 年約 300 ppm(曲線至此為止)。(c) ²⁰⁶Pb/²⁰⁷Pb 比值(橫軸 1.170 至 1.182,以黑點表示,各點的年代由下往上約為):1725、1750、1765、1785、1805、1817 年的比值約 1.178(幾乎不變);1837 年約 1.1791、1857 年約 1.1792、1877 年約 1.1794、1895 年約 1.1795、1908 年約 1.1796、1920 年約 1.1799(最高);1925 年約 1.1794、1931 年約 1.1783、1935 年約 1.1778、1938 年約 1.1773、1943 年約 1.1766、1946 年約 1.1760、1948 年約 1.1744、1954 年約 1.1732、1969 年約 1.1710、1977 年約 1.1696。1817 年與 1837 年兩點之間沒有資料點。]",
        "question": "工業革命的一大突破就是大量使用蒸氣機作為運輸動力,從圖 15 的數據分析,可以推論此地運輸業的蒸汽機應在何時開始大量使用煤作為燃料?推論依據為何?(4分)",
        "explanation": "(112學測自然第54題,非選擇題,4分,年代1分+推論3分)參考答案:年代部分:1820~1840年間;推論部分:從圖15(c)可知,²⁰⁶Pb/²⁰⁷Pb 比例在此時間範圍內顯著增加,因為開始大量使用煤作為燃料後,會提高環境的 ²⁰⁶Pb/²⁰⁷Pb 比例。評分原則:年代部分與推論部分獨立計分,滿分分別為1分及3分;年代寫在1820到1840年間任一年代或範圍者,得1分,其餘作答不給分;推論部分能完整說明推論依據者,包括「²⁰⁶Pb/²⁰⁷Pb 比例或圖15(c)」、「該值短時間內有明顯變化」、「變化方向朝煤的 ²⁰⁶Pb/²⁰⁷Pb 比例接近」者,得3分;未能完整說明推論依據者得部分分數;說明錯誤或答非所問者不給分。"
