        "passageTitle": "第16-17題題組",
        "passage": "海水去鹽淡化,可讓水資源再利用。某實驗室發現咖啡渣可作為水純化的材料。首先將咖啡渣在極高溫下碳化成奈米材料,再混以具有油脂特性的無色透明矽烷,均勻地灑在一杯海水的表面上,然後放置在一具有斜度上蓋的透明容器(如圖5所示),經在太陽光照射之下,底部漸漸發現有經過凝結後的純水。\n研究人員針對四種情況,分別是(甲)未照光、(乙)照光、(丙)照光並灑上碳化咖啡粉,以及(丁)照光並灑上混有矽烷的碳化咖啡粉,且後兩種情況使用同樣重量的咖啡粉。在同樣的時間內,測量水杯重量的減少程度,並將實驗結果繪製成圖6。\n[圖5示意(非官方文字):一個上蓋傾斜的透明容器,容器內中央放一個盛海水的杯子,海水表面灑有碳化後粉末(圖中標示「碳化後粉末」、「海水」);杯子旁的容器底部標示為「純水」。]\n[圖6示意(非官方文字):橫軸為時間(min,0 至 60),縱軸為重量的改變(kg/m²,由 0 往下至 -1),四條由原點出發、隨時間下降(水杯重量減少)的曲線,60 分鐘時約為:甲(未照光,圓點)約 -0.1,幾乎持平;乙(照光,方塊)約 -0.46;丙(照光並灑上碳化咖啡粉,三角形)約 -0.6;丁(照光並灑上混有矽烷的碳化咖啡粉,倒三角形)約 -1.0,下降最多,約 30 分鐘後接近直線下降,約 40 分鐘時約 -0.62、50 分鐘時約 -0.82、60 分鐘時約 -1.02。]",
