        "passageTitle": "第22-23題題組",
        "passage": "高能的粒子束或X光束可用於治療惡性腫瘤(癌症)。每單位質量的人體組織所吸收的射束能量稱為吸收劑量。射束通常對準腫瘤照射,癌細胞與正常細胞吸收射束的能量後,DNA會遭到破壞,而癌細胞死亡的機率較正常細胞為高。\n圖8顯示的是電子、質子、和兩個能量不同的X光等四種射束之吸收劑量隨進入表皮深度的變化。圖中各射束名稱下,註明該射束中單一粒子或光子入射人體時的能量,其中1.0 MeV約為 1.6×10⁻¹³ J。\n[圖8示意(非官方文字):橫軸為進入表皮深度(公分,0 至 15),縱軸為細胞組織吸收劑量(未標數值;以下以各曲線最高峰約為 1 作相對比較)。共四條曲線:電子束(4.0 MeV):在表皮處吸收劑量已接近最高,約 1 公分內達高峰,之後急速下降,約 2 公分處降為零。X光束(4.0 MeV,實線):約 0.5 公分處達高峰,之後單調緩慢下降,約 5 公分處約 0.55、10 公分處約 0.4、15 公分處仍約 0.35~0.4。X光束(20 MeV):表皮處約 0.45,隨深度上升,約 2 公分處達高峰,之後緩慢下降,約 5 公分處約 0.85、10 公分處約 0.7、15 公分處仍約 0.55~0.6;在約 2 至 10 公分之間,其吸收劑量高於其他三條曲線。質子束(150 MeV):表皮處只有約 0.35,隨深度緩慢上升(約 8 公分處約 0.45,此處與 4.0 MeV X光束曲線相交),約 11~12 公分處出現非常尖銳、高度與其他射束高峰相近的最高峰,之後迅速下降,約 13 公分處降為零。電子束與質子束在其降為零的深度之後不再有吸收劑量,兩條X光束曲線到 15 公分處仍不為零。]",
