        "explanation": "(113學測自然第38題,非選擇題,共4分)\n滿分參考答案:\n(a)是(1分)。\n(b)生長速率提升(或單位時間重量變重)(1分);飼料攝取(量)下降(或飼料轉化率下降)(或飼料轉化率由2.3下降至約1.9)(1分);表示肉雞能更有效率將飼料轉換成雞肉(或較少的飼料可轉化成較多的雞肉)(1分)。\n評分原則:(a)明確回答是、有等,得1分;寫出其他答案(例如:否),得0分。(b)三點各1分:正確說明生長速率提升、正確說明飼料攝取的變化、正確說明兩者間的關係來支持結論;須同時正確說明生長速率提升、飼料攝取變化,以及兩者之間的關係,才能獲得該小題滿分3分;若說明理由不正確或單位錯誤,均得0分。"
