        "passageTitle": "第37-39題題組",
        "passage": "媽媽去購物商場買烤全雞,聽老闆說這些雞只需要約40天就達到上市的尺寸。近數十年,高產肉雞育種選拔計畫有著重要的突破,在持續的選拔下,以56日齡雞隻為例,可從1957年的905克/隻提升到2005年時的4202克/隻(如圖14所示)。此外,為降低飼養成本,育種過程也會參考肉雞的飼料轉化率,即肉雞每單位肉重所需的飼料重量(如圖15)。\n[圖14示意(非官方文字):三隻雞的照片並排,由左至右分別標示 1957、1978、2005,體型依序變大,2005 年的雞最大最壯。]\n[圖15示意(非官方文字):橫軸為西元(年,1970 至 2005),縱軸為飼料轉化率(1.5 至 2.4)。許多黑點大致隨年代下降,並有一條由左上往右下的直線(趨勢線):約 1970 年時飼料轉化率約 2.3,約 1985 年約 2.1,約 2000 年約 1.85,2005 年約 1.8。]",
