        "passageId": "science-real-113-g40",
        "passageTitle": "第40-43題題組",
        "passage": "捕蠅草捕蟲的趣事是生物適應的現象之一。捕蠅草生長在養分及礦物質缺乏的溼地,為了生存,它演化出肉食性的特質。它的葉片特化成捕器,是可以吸引、捕抓及消化小型節肢動物的器官。捕器閉合的物理機制源自於葉片細胞的膨脹與收縮。當水分從內層細胞流入外層細胞時,內層細胞收縮、外層細胞膨脹,因而造成葉片彎曲而閉合(圖17)。\n[圖17示意(非官方文字):左圖為捕蠅草捕器張開的示意圖(兩側葉片向兩邊展開呈 V 字形),圖中標示各部位名稱:內層細胞、外層細胞、葉片、中肋(兩側葉片相接處的中央)、觸毛(長在葉片內側);右圖為捕器閉合的示意圖,兩側葉片合攏。]\n捕器葉片的內側有觸毛,可感應獵物的觸動。每次觸發觸毛會產生一個電位。研究顯示,產生第一次電位時,葉片仍會保持張開,並記憶第一次的觸發。若在20秒內發生第二次觸發,葉片才會快速閉合困住獵物。科學家在葉子中肋和葉片分別插入電極進行充電,以模擬觸毛被觸發時產生電位的現象,他們發現無論是分段充電,還是連續充電,充電電量都要達到14 μC,葉片才會在大約0.5秒內快速閉合。然而,若將捕蠅草的土壤浸潤在pH值高於4.5的溶液中,就算觸發觸毛產生電位,也無法讓葉子閉合。",
