        "type": "written",
        "question": "甲同學看完了以上對捕蠅草的敘述後,提出自己的看法:「觸毛第一次被觸發時,葉子中肋和葉片間會進行第一次充電,充電電量小於 14 μC,第二次觸發會進行第二次充電,讓葉子中肋和葉片間的儲存電量達到 14 μC。由於儲存的電量會慢慢散去,所以若沒有在 20 秒內進行第二次觸發,則第二次觸發是無法讓總電量達到 14 μC。」甲同學想證明自己的看法,設計了幾個實驗進行探究。將設計的實驗變因及預期觀察到的現象(即應變變因與操縱變因間的關係)填入表格的空格(①~④)中。(4分)\n探討的問題 | 控制變因 | 操縱變因 | 應變變因 | 甲同學預期觀察到的現象\n第一次觸發觸毛後,葉子中肋和葉片之間的儲存電量隨時間變化的關係 | 培養土的 pH 值 | 時間 | (①) | •第一次觸發的充電電量小於 14 μC;•(②)\n連續兩次觸發的時間間隔對葉子中肋和葉片之間累積的儲存電量之影響 | 培養土的 pH 值 | (③) | 葉子中肋和葉片之間的儲存電量 | •連續兩次觸發的時間間隔越大,累積的儲存電量越低;•(④)",
