        "question": "表 5 為各種產物的價格(元/公斤)與以每莫耳電子計算所轉換產物的價格(元/莫耳電子)。其中,正丙醇價格尚未計算完成,回答下列各問題。(原子量 C=12.0、H=1.00、O=16.0)\n表 5\n產物 | 市價(元/公斤) | 轉換產物的價格(元/莫耳電子)\n甲醇 | 16.9 | 0.090\n乙烯 | 40.7 | 0.095\n正丙醇 | 45.0 | ?\n(a)請列式計算正丙醇轉換產物的價格為何?(2分)\n(b)另有一電化學催化系統,只會產生甲醇與正丙醇。已知每產生1莫耳此混合產物需消耗10.8莫耳電子,此混合產物中,列式計算甲醇與正丙醇的莫耳數比為何?(2分)",
        "explanation": "(113學測自然第49題,非選擇題,共4分)\n滿分參考答案:\n(a)(2分)正丙醇轉換產物的價格 = 45 元 ÷ [(1000 g ÷ 60 g/mol) × 18 e⁻] = 0.15(元/莫耳電子)。\n(b)(2分)假設甲醇的莫耳數為 m,則正丙醇的莫耳數為 (1−m);m×6 + (1−m)×18 = 10.8,m = 0.6;甲醇的莫耳數為 0.6,正丙醇的莫耳數為 (1−0.6) = 0.4;故甲醇與正丙醇的莫耳數比為 0.6 : 0.4 = 3 : 2。\n評分原則:(a)列式正確得1分,答案正確再得1分;列式正確但答案不正確只得1分;只寫答案沒計算過程則不給分。(b)列式正確得1分,答案正確再得1分;列式正確但答案不正確只得1分;只寫答案沒計算過程則不給分。"
