        "passageTitle": "第50-53題題組",
        "passage": "在寒武紀以前的地層中,可找到由氧化鐵與二氧化矽細粒反覆堆疊形成的「縞狀(帶狀)鐵礦床」,是重要的鐵礦來源。約24億年前的地層中,更普遍地出露厚層的縞狀鐵礦床。縞狀鐵礦床形成原因的假設模型,是由亞鐵離子(Fe²⁺)與氧氣作用生成氧化鐵(Fe₂O₃及Fe₃O₄)沉澱所致。而 Fe²⁺ 是由海底岩漿噴發所形成,氧氣則是由藍綠菌行光合作用所產生。\n圖20彙整了一些地球歷史事件,包括化石紀錄、縞狀鐵礦形成時段與相對含量,以及大氣中氧氣含量相對於現今濃度的變化。\n[圖20示意(非官方文字):橫軸為距今時間(十億年前,0.0 至 3.5;左端 0.0 為現今)。圖上方有三條箭頭(箭頭皆指向現今),表示化石紀錄:動物的箭頭由約 0.6 延伸到 0.0;真核生物的箭頭由約 1.85 延伸到 0.0;細菌的箭頭由 3.5(圖的右端)延伸到 0.0。下方的圖有兩條縱軸:左縱軸為氧氣相對含量(對數刻度,1.0、10⁻¹、10⁻²、……至 10⁻⁶),氧氣以一條黑色的曲線帶表示:約 0.0 至 0.5 十億年前在 1.0 附近(約 0.15 處略高後緩降);約 0.6~0.7 十億年前急降到約 0.03(介於 10⁻² 與 10⁻¹ 之間);之後從約 0.7 到約 2.0 十億年前大致維持在這個平坦水準;約 2.0 到 2.3 十億年前急劇下降(約 2.2~2.3 最陡),降到約 10⁻⁵~10⁻⁶;約 2.4 至 3.5 十億年前一直維持在 10⁻⁶~10⁻⁵ 的極低水準。右縱軸為縞狀鐵礦相對含量(0.0、0.5、1.0),以斜線長條表示:約 0.58 與 0.62 十億年前各有一極小的長條(約 0.1~0.2);約 0.72 十億年前有一條約 0.75;約 1.85 十億年前有一條約 0.75;約 2.4~2.5 十億年前有一條最高(1.0);約 2.5~2.65 約 0.2;約 2.65~2.8 約 0.75;約 2.8~2.95 約 0.1;約 2.95~3.1 約 0.2;約 3.1 至 3.5 十億年前之間的長條都很小(約 0.03~0.07)。]",
