        "sourceYear": 113,
        "part": "混合題或非選擇題",
        "type": "written",
        "question": "有研究指出,在幾乎無氧的環境下,無氧光自營細菌在光照的情況下,可將亞鐵離子反應產生一些產物,其平衡反應式如下:\n24Fe²⁺ + 6CO₂ + xH₂O → (CH₂O)₆ + yFe(OH)₃ + zH⁺\n(a)寫出x,y和z值(說明求得數值的過程)。(3分)\n(b)(CH₂O)₆為有機化合物,而生活中常見的有機物質有醣類、蛋白質、油脂及核酸等,試問(CH₂O)₆可能屬於其中哪一類的化合物?(1分)",
        "explanation": "(113學測自然第51題,非選擇題,共4分)\n滿分參考答案:\n(a)24Fe²⁺ + 6CO₂ + xH₂O → (CH₂O)₆ + yFe(OH)₃ + zH⁺;x = 66、y = 24、z = 48(3分)。(補充推導,非官方文字:Fe 守恆得 y = 24;電荷守恆 24×(+2) = z 得 z = 48;O 守恆 12 + x = 6 + 3×24 得 x = 66。)\n(b)醣類或碳水化合物(1分)。\n評分原則:(a)說明x、y、z的過程正確且數值正確,各給1分;只寫答案沒有計算過程,則不給分。(b)寫醣類或碳水化合物可得1分;答非所問或未作答者得0分。"
