        "passage": "化合物甲與乙是啤酒苦味最主要的來源,其結構如圖 6 所示。在異辛烷溶液中,這兩個分子都會吸收波長 275 nm 的紫外光,且吸光度與濃度成正比。化合物甲與乙皆為弱酸,在水中可部分分解離出 H⁺與它們各自的酸根。\n[圖6示意(非官方文字):化合物甲與化合物乙的骨架結構式圖(含 C=O、OH 及數個含碳支鏈);因結構圖無法忠實以文字呈現,此處不轉錄,本題組保留的題目不需使用。]\n「國際苦度單位」是啤酒釀製過程的一項重要指標,大部分啤酒的苦度介於 10 到 100 之間,其簡易測量方法如下:\n步驟一、取 5.0 mL 的啤酒樣品,加入 12.5 mL 的異辛烷和 0.5 mL 的酸\n步驟二、充分搖晃混合,待液體分層後,測量異辛烷層在 275 nm 的吸光度\n步驟三、此吸光度乘以 50 即為該啤酒樣品的「苦度」\n淑芬同學對某品牌的啤酒進行了四次的苦度測量,每次的實驗條件如表 1 所示。\n表 1\n實驗 | 啤酒(mL) | 酸的種類與量(mL) | 異辛烷(mL) | 苦度\n一 | 5.0 | 鹽酸 12 M HCl(aq) 0.5 | 12.5 | 26.5\n二 | 5.0 | 硫酸 6 M H₂SO₄(aq) 0.5 | 12.5 | 28.7\n三 | 5.0 | 醋酸 1 M CH₃COOH(aq) 0.5 | 12.5 | 8.8\n四 | 5.0 | 鹽酸 12 M HCl(aq) 0.5 | 25.0 | ?",
