        "passageTitle": "第37-39題題組",
        "passage": "虱目魚原為海生魚類,但可被漁民養殖在鹼水池或淡水池裡,而且淡水養殖的生產效率高於鹼水養殖。虱目魚不耐低溫,發生寒害時,鹼水池的虱目魚死亡率遠低於淡水池的。學者研究發現,鹼水魚耐寒的特性可能與調鈣蛋白(Regucalcin, RGN)有關。\nRGN 能與鈣離子結合,藉著鈣離子所調控的基因表現網絡,影響生物體對低溫的調適能力。為此,研究者先檢測虱目魚不同器官的組織,測得 RGN 基因所表現的 mRNA 量(RGN mRNA)。此量值相對於管家基因(即經常性表現維持細胞存活之一般基因)的數值如圖 8 甲所示。同時,也測得長期養殖在鹼水池和淡水池虱目魚的 RGN mRNA 數量差異,如圖 8 乙所示。\n[圖8甲示意(非官方文字):長條圖,橫軸為組織部位(腦、鰓、心、腸、腎、肝、肌肉、脾),縱軸為 RGN mRNA 量(相對值,0 至 1.5)。各部位約為:腦 0.07、鰓 0.02、心 0.05、腸 0.39、腎 0.11、肝 1.25(最高)、肌肉 0.13、脾 0.03。]\n[圖8乙示意(非官方文字):長條圖,橫軸為養殖環境(淡水、鹼水),縱軸為 RGN mRNA 量(相對值,0 至 4);圖例:白色長條為 28°C,黑色長條為 18°C。淡水:28°C 約 0.3、18°C 約 3.2;鹼水:28°C 約 1.15、18°C 約 0.42。]",
