        "passageTitle": "第37-39題題組",
        "passage": "虱目魚原為海生魚類,但可被漁民養殖在鹼水池或淡水池裡,而且淡水養殖的生產效率高於鹼水養殖。虱目魚不耐低溫,發生寒害時,鹼水池的虱目魚死亡率遠低於淡水池的。學者研究發現,鹼水魚耐寒的特性可能與調鈣蛋白(Regucalcin, RGN)有關。\nRGN 能與鈣離子結合,藉著鈣離子所調控的基因表現網絡,影響生物體對低溫的調適能力。為此,研究者先檢測虱目魚不同器官的組織,測得 RGN 基因所表現的 mRNA 量(RGN mRNA)。此量值相對於管家基因(即經常性表現維持細胞存活之一般基因)的數值如圖 8 甲所示。同時,也測得長期養殖在鹼水池和淡水池虱目魚的 RGN mRNA 數量差異,如圖 8 乙所示。\n[圖8甲示意(非官方文字):長條圖,橫軸為組織部位(腦、鰓、心、腸、腎、肝、肌肉、脾),縱軸為 RGN mRNA 量(相對值,0 至 1.5)。各部位約為:腦 0.07、鰓 0.02、心 0.05、腸 0.39、腎 0.11、肝 1.25(最高)、肌肉 0.13、脾 0.03。]\n[圖8乙示意(非官方文字):長條圖,橫軸為養殖環境(淡水、鹼水),縱軸為 RGN mRNA 量(相對值,0 至 4);圖例:白色長條為 28°C,黑色長條為 18°C。淡水:28°C 約 0.3、18°C 約 3.2;鹼水:28°C 約 1.15、18°C 約 0.42。]",
        "question": "為了試驗虱目魚對抗低溫之調適能力,研究者分別將畜養於 28°C淡水池和鹼水池的魚移置 18°C,並逐時測量 RGN mRNA 的量,再以各自 0 時數值為基準值進行校正,得資料如表 2 所示。\n表 2(RGN mRNA 相對量)\n養殖池別 | 0 | 6 | 12 | 24 | 48 | 96 | 168(時間,小時)\n甲 | 1.0 | 1.3 | 1.4 | 1.8 | 2.5 | 3.2 | 3.3\n乙 | 1.0 | 3.0 | 3.5 | 2.5 | 1.3 | 0.9 | 0.8\n[圖9甲示意(非官方文字):橫軸為小時(0、24、48、72、96、120、144、168),縱軸為 mRNA 相對量(0 至 4);黑點(0, 1.0)、(6, 1.3)、(12, 1.4)、(24, 1.8)、(48, 2.5)、(96, 3.2)、(168, 3.3)以一條平滑曲線連接,曲線先上升、後期趨於平緩。]\n[圖9乙示意(非官方文字):座標軸與圖 9 甲相同,但只有 (0, 1.0)、(96, 0.9)、(168, 0.8) 三個黑點,其中 96 與 168 小時兩點以線段相連;其餘時間點尚未畫出。]\n(a)圖 9 甲為表 2 養殖池甲之虱目魚移到 18°C環境下,其 RGN mRNA 生成量隨時間的變化情形。試參考圖 9 甲的繪圖方式,於圖 9 乙中補足表 2 養殖池乙之虱目魚 RGN mRNA 之變化趨勢。(1分)\n(b)從圖 8 及圖 9 甲綜合判斷圖 9 甲應該是來自哪種養殖池?(擇一:鹼水或淡水,1分)並說明判斷理由。(2分)",
        "explanation": "(114學測自然第38題,非選擇題,共4分)\n滿分參考答案:\n(a)(1分)在圖 9 乙補上 (6 小時, 3.0)、(12 小時, 3.5)、(24 小時, 2.5)、(48 小時, 1.3) 四個點,連同原有的 0、96、168 小時的點,以平滑趨勢線連接:曲線由 1.0 快速上升至約 12 小時的最高點 3.5,之後下降,約 48 小時降至 1.3,96 小時 0.9、168 小時 0.8。\n(b)來自淡水養殖池(1分)。理由(2分):因為長期(相對長期)(已調適)(後期)的低溫下,淡水池虱目魚的 RGN mRNA 表現量較高。\n評分原則:(a)必須 4 個點均可正確辨認且點之間有趨勢線連接,才能獲得 1 分;趨勢線上若有多餘的點或缺少的點、只有線條沒有點、或只有點沒有連成趨勢線,均不給分。(b)養殖池勾選占 1 分,判斷理由占 2 分;須先正確勾選淡水養殖池,才能獲得判斷理由的分數;判斷理由須同時寫出(1)長期、後期或已調適等時間點的敘述以及(2)RGN mRNA 表現量較高兩方面,才能獲得該部分全部分數 2 分;若僅寫出 RGN mRNA 表現量較高等敘述,僅獲得 1 分。"
