        "type": "multi",
        "passageId": "science-real-114-g40",
        "passageTitle": "第40-43題題組",
        "passage": "海洋表面顏色(水色)的觀測,在海洋生態系的生物地球化學現象研究上極為關鍵。生態系的基礎生產力是指初級生產者所生產的有機物質。植物性浮游生物能夠吸收二氧化碳進行光合作用,是海洋生態系主要的生產者,其數量多寡影響該海域各級消費者之生物量。\n通常表層營養鹽豐富的海域,有利於生產者行光合作用及繁殖,可增加基礎生產力。植物性的生產者之體內含有葉綠素會使水色從偏藍色轉向偏綠。因此,利用衛星遙測水色之變化,即可以推估當地海域的基礎生產力,進一步估計該海域之資源量。\n然而,海水中葉綠素的濃度會受到海洋或大氣環境的影響而有很大的變化,圖 10 顯示某聖嬰年及某反聖嬰年十二月時(圖 10 甲與圖 10 乙並未直接對應何者為聖嬰年或反聖嬰年),由太平洋水色影像轉換的葉綠素濃度灰階圖,它能夠明顯反映海表面植物性浮游生物的多寡。圖中灰階越接近黑色(灰階值越小)代表葉綠素濃度越高,反之灰階越接近白色(灰階值越大)代表葉綠素濃度越低。\n[圖10示意(非官方文字):兩幅以太平洋為中心的地球儀形灰階衛星影像(甲、乙),各標有赤道線與「美國」,下方灰階色條由白色(255,低濃度)至黑色(0,高濃度)。影像的灰階分布細節無法以文字忠實描述,本題組保留的題目(第42、43題)不需使用此圖。]",
        "question": "某海洋生態系中,矽藻是磷蝦的食物,而磷蝦為鯨魚的食物。矽藻的生長需要鯨魚排泄物中的鐵離子。依此敘述,若此海域鯨魚瀕臨局部滅絕,經長時間觀察可能會發現哪些現象?(應選 2 項)",
