        "question": "(a)康芮颱風過去路徑幾近直接朝向臺灣而來,試問形成這種路徑主要受到什麼天氣系統影響?(1分)\n(b)若康芮颱風以東南往西北的方向通過蘭嶼上空,試問颱風中心通過蘭嶼前後三小時左右,當地主要風向最可能的變化為何?(2分)(作答格式:「____風轉____風」)\n(c)假使此時南海大約同一個緯度上還有另一強度相當的颱風,此兩颱風彼此會互相影響,產生藤原效應。藤原效應是兩個颱風相互靠近牽制的現象,會使兩個颱風移動路徑受到影響,通常使兩颱風以共同質量中心作逆鐘向互繞運動,增加路徑預報之難度。若康芮颱風和此位在南海的颱風產生藤原效應,中央氣象署將會對康芮颱風的移動路徑往哪一個方向做修正?(1分)",
        "explanation": "(114學測自然第46題,非選擇題,共4分)\n滿分參考答案:\n(a)太平洋高壓(1分)。\n(b)東北風轉西南風(2分)(第一格寫「東北」、第二格寫「西南」)。\n(c)北方(1分)。\n評分原則:(a)正確寫出「太平洋高壓」等同義詞者,得1分。(b)第一格正確寫出「東北」等同義詞者得1分;第二格正確寫出「西南」等同義詞者得1分;兩格所寫風向不完全正確,但大致方向之搭配仍正確者,得部分分數。(c)正確寫出「北」等同義詞者,得1分。答非所問或未作答者不給分。"
