        "passageTitle": "第47-49題題組",
        "passage": "2024 年諾貝爾物理獎主題是仿效腦部神經網路,藉由變化數據節點之間連通的強弱,奠定人工智慧(AI)的基礎。圖 12 為探究神經細胞之間的連通機制,是 1963 年諾貝爾生理學或醫學獎主題的示意圖。通過神經細胞膜傳訊的機制放大圖如圖 13。\n電路模型如圖 14,模型中 C_M 代表細胞膜的內、外表面,以及其間的不導電物質。R_Na 與 R_K 為可變電阻,可以改變神經細胞之間連通的強弱,以處理資訊。其中 E_Na、E_K 與 E_L 分別為離子 Na⁺、K⁺與其他離子的平衡電壓,相當於等效電池,可以推送或聚集對應的離子,維持細胞內外離子濃度差異。\n已知平衡電壓為 E = −(αT/e) log(n_內/n_外),其中 n_內與 n_外分別為細胞內部與外部的離子濃度,α > 0 為轉換常數,T 為絕對溫度,e 為基本電量。依據以上資料回答下列問題。\n[圖12、13示意(非官方文字):圖 12 為兩個神經細胞(神經元)相連的示意圖,以圓圈標出其連接處,箭頭示意訊息傳遞;圖 13 為該連接處(細胞膜傳訊處)的放大圖。]\n[圖14示意(非官方文字):神經細胞膜電路模型。上方導線標「細胞外部」、下方導線標「細胞內部」。左側為代表細胞膜的電容 C_M(以點狀方塊表示,接在上、下兩導線之間)。右側有三條並聯支路,各接在上、下兩導線之間,每條支路都是一個電阻與一個電池串聯:第一支路為可變電阻 R_Na 與電池 E_Na(電池上端標「−」、下端標「+」);第二支路為可變電阻 R_K 與電池 E_K(上端「+」、下端「−」);第三支路為電阻 R_L 與電池 E_L(上端「+」、下端「−」)。]",
