        "passageTitle": "第50-54題題組",
        "passage": "奈米級的二氧化鈦(TiO₂)為一種光觸媒材料,當此光觸媒照光之後,可將周遭環境中的汙染物質分解,達到去汙與除臭的效果。而其原理主要是二氧化鈦光觸媒照光後,電子會從價帶躍遷到導電帶,使得二氧化鈦表面生成氫氧自由基(·OH)與超氧離子(O₂⁻),此兩者的活性很大可以將有機物分解成二氧化碳和水,達到淨化效果。\n此外,二氧化鈦光觸媒亦可在光的照射下催化水裂解產生氫氣和氧氣,為綠色能源與永續發展的重要觸媒。由於二氧化鈦光觸媒的導電帶與價帶的能階差(亦稱為能隙)大約為 3.20 eV,故所照的光源中光子能量必須高於此能量才能啟動催化反應,為了提升其催化活性與效率,許多研究利用不同的金屬摻雜來改善材料特性。\n某研究團隊發現於二氧化鈦奈米材料中摻雜少量的鋅離子(Zn-TiO₂)後,會改變能隙,並提升催化水裂解的效率。根據上述資訊及所學,回答下列問題。",
        "question": "(a)欲啟動未摻雜二氧化鈦光觸媒的催化反應,可允許之最長波長約為多少 nm?(h = 6.63×10⁻³⁴ J·s、1 eV = 1.6×10⁻¹⁹ J、真空光速 = 3.0×10⁸ m/s)(2分)\n(b)摻雜少量的鋅離子於二氧化鈦(Zn-TiO₂)後,恰可以使用波長 400 nm 的光激發催化。試在答題卷作答區中填入摻雜鋅離子後的奈米級二氧化鈦能隙變化,並說明理由。(2分)\n[作答表格示意(非官方文字):兩欄比較。能隙:未摻雜的二氧化鈦(TiO₂)為 3.2 eV;摻雜少量鋅離子於二氧化鈦(Zn-TiO₂)為「____ 3.2 eV(空格填入 >、< 或 =)」。另有「說明理由」一列。]",
        "explanation": "(114學測自然第51題,非選擇題,共4分)\n滿分參考答案:\n(a)(2分)E = hf = hc/λ,故最長波長 λ = hc/E = (6.63×10⁻³⁴ J·s × 3.0×10⁸ m/s)/(3.2 eV × 1.6×10⁻¹⁹ J/eV) ≈ 388×10⁻⁹ m ≈ 390 nm。\n(b)(2分)能隙:「<」3.2 eV(摻雜後能隙小於 3.2 eV)。理由一:由 E = hf = hc/λ,可知 E ∝ 1/λ。由於摻雜鋅離子之二氧化鈦的啟動催化反應光源的波長可為 400 nm,較未摻雜前所須使用的光源波長 390 nm 更長,故其能隙應小於 3.2 eV。理由二:依據題幹敘述,摻雜鋅離子後的二氧化鈦之能隙會改變、且可提升催化效率,由此可推知其能隙應下降,讓能量較低的光也可使其電子躍遷、促進催化效率。\n評分原則:(a)寫出如滿分參考答案所列,計算過程合理正確,即得該題滿分 2 分。(b)寫出如滿分參考答案所列,理由說明合理正確,即得該題滿分 2 分。"
