        "passage": "烷類在充足的氧氣下,可進行燃燒反應,產生二氧化碳,並釋出熱量,可作為燃料使用。市售的液化天然氣是以甲烷為成分,液化石油氣則是丙烷與丁烷的混合物。表 3 為幾種烷類的分子式、分子量及莫耳燃燒熱。1 莫耳碳氫化合物完全燃燒生成二氧化碳和水時,所釋出的熱量稱為莫耳燃燒熱。\n表 3\n化合物 | 分子式 | 分子量 | 莫耳燃燒熱(千焦耳/莫耳)\n甲烷 | CH₄ | 16 | 890\n乙烷 | C₂H₆ | 30 | 1560\n丁烷 | C₄H₁₀ | 58 | 2874\n戊烷 | C₅H₁₂ | 72 | 3509\n辛烷 | C₈H₁₈ | 114 | 5460",
