        "passage": "小芬修習「探究與實作」後,知道香蕉的果皮與果肉中,富含鹼金屬與鹼土金屬元素的鹽類。她想從香蕉中提取鉀鹽,經老師指導與蒐集資料後,進行實驗,實驗步驟與紀錄如下:\n步驟 1. 整理資料,得每一百克香蕉所含成分如表 5;而表 6 則整理出鹼金屬/鹼土金屬化合物,在 30°C 時的溶解度(g/100 g 水)。\n表 5\n成分 | 重量(g) | 礦物質 | 重量(mg)\n醣類 | 28 | 鈣 | 150\n脂肪 | 0.5 | 鎂 | 130\n蛋白質 | 1.5 | 磷 | 20\n胺基酸 | 0.05 | 鉀 | 390\n維生素 | 0.1 | 鈉 | 1\n水分 | 69 | 鋅 | 0.1\n表 6(陰離子 \\ 陽離子 對應之溶解度,g/100 g 水)\n陽離子\\陰離子 | SO₄²⁻ | ClO₃⁻ | ClO₄⁻ | NO₃⁻ | CO₃²⁻\nNa⁺ | 110 | 105 | 209 | 104 | 110\nK⁺ | 130 | 10 | 1.3 | 160 | 120\nMg²⁺ | 24 | 150 | 100 | 140 | <0.01\nCa²⁺ | 0.3 | 130 | 190 | 150 | <0.01\n步驟 2. 收集 1 公斤香蕉,清洗、烘乾後,混合木炭後將有機物完全燃燒,礦物質完全變成碳酸鹽與氧化物固體。\n步驟 3. 將固體秤重、磨成粉末,加入 50 mL 熱水,攪拌並靜置過夜。\n步驟 4. 以濾紙濾除不溶物。已知表 6 中五種陰離子的銨鹽均可溶於水,依據表 6,逐步加入 NH₄ClO₄ 於濾液中,溶液會出現沉澱,繼續添加,直到沉澱不再出現。\n步驟 5. 以濾紙收集沉澱物、乾燥並秤重。移入 600°C 的烘箱內加熱,重量減少,反覆加熱,直到重量不再變化,最終重量比原先減少 46.2%。推測原因,應是在加熱過程中發生分解反應。依據上述,回答下列問題。(莫耳質量:NaClO₄ = 122.5 g/mol、KClO₄ = 138.5 g/mol、NaCl = 58.5 g/mol、KCl = 74.5 g/mol)",
        "question": "在上述步驟中,包括下列哪些實驗方法?(應選 2 項)",
