        "passageTitle": "第37-39題題組",
        "passage": "巴西龜(Trachemys scripta)的性別是由受精卵孵化時的環境溫度所決定。將卵置於 26°C,性別決定基因 Dmrt1 會表現出來,胚胎發育為雄性。將卵置於 32°C,Dmrt1 基因不會表現,胚胎發育為雌性。\n進一步的研究發現,Kdm6b 基因會影響 Dmrt1 基因的表現與否,即 Kdm6b 蛋白質的量相對較高時,會促進 Dmrt1 基因表現 RNA,進而產生更多的 Dmrt1 蛋白質。在 26°C 時,Kdm6b 蛋白質的表現量相對較高,於是活化 Dmrt1 基因。在 32°C 時,Kdm6b 蛋白質的表現量相對低,使得 Dmrt1 基因幾乎不表現。",
        "question": "將文本的研究發現歸納總結,可用示意圖 13 表示。\n[圖13示意(非官方文字):流程圖。左側「32°C」有箭頭(向下箭頭)指向方框「Kdm6b」;方框「Kdm6b」有箭頭(向下箭頭,標「(↓)」)指向「Dmrt1(↓)」,再指向「雌龜」。左下「26°C」有箭頭(向上箭頭)指向同一方框「Kdm6b」;並有箭頭(向上箭頭,標「(↑)」)指向「Dmrt1(↑)」,再指向「雄龜」。]\n(a) 因此,可推論在 26°C 孵化的巴西龜受精卵,若在適當時間點對其胚胎注射抑制 Kdm6b 基因表現的藥物,則此幼龜的性別為何?(2分)\n(b) 承(a)題,相較於未經藥物處理的 26°C 孵化胚胎,此胚胎中 Dmrt1 基因及 Kdm6b 基因的表現量變化為何(20字以內)?(2分)",
