        "passageTitle": "第40-43題題組",
        "passage": "植物的花蜜富含香氣,可吸引某些鳥類前來取食。鳥類吸取花蜜之時,身體會接觸到花蕊與花粉,間接幫助植物授粉及繁衍後代。研究發現某野生菸草,其花蜜的主要成分為具香氣的芐丙酮與具毒性的尼古丁,兩者結構式如圖 15。\n[圖15示意(非官方文字):芐丙酮與尼古丁的骨架結構式圖(各含苯環、雜環與支鏈);因結構圖無法忠實以文字呈現,此處不轉錄,本題組保留的題目(第40、41題)不需使用。]\n為了探究這兩種成分對蜂鳥取食花蜜及對菸草繁衍的影響,研究者創造了花蜜中只含芐丙酮、只含尼古丁、以及兩者都缺乏的三型基改菸草。\n然後,將這三型基改菸草與野生型菸草分別種植在不同樣區,於菸草開花期間同步記錄各區每天受蜂鳥到訪的花朵數目(圖 16 甲)、蜂鳥在每朵花停留時間的平均值(圖 16 乙)、果實之成熟率(圖 16 丙)與花朵中花蜜剩餘的體積(圖 16 丁)。\n圖 16 之甲~丁橫軸為花蜜中含芐丙酮及尼古丁的狀態,如表 7 的說明。依據圖文資料,回答 40~43 題。\n表 7\n圖示 | 狀態\n+/+ | 含芐丙酮及尼古丁\n+/− | 含芐丙酮,但無尼古丁\n−/+ | 無芐丙酮,但含尼古丁\n−/− | 不含芐丙酮與尼古丁\n[圖16示意(非官方文字):四張長條圖(甲、乙、丙、丁),橫軸皆為基改狀態(+/+、+/−、−/+、−/−)。甲(每天受訪花朵數,朵,縱軸約30~55):+/+ 約53、+/− 約33、−/+ 約54、−/− 約31。乙(平均停留時間,秒,縱軸約1.0~2.0):+/+ 約1.2、+/− 約1.85、−/+ 約1.45、−/− 約1.8。丙(果實成熟率,%,縱軸0~40):+/+ 約35、+/− 約13、−/+ 約12、−/− 約14。丁(花蜜剩餘體積,微升,縱軸0~1.6):+/+ 約1.15、+/− 約0.7、−/+ 約1.35、−/− 約1.1。]",
