        "question": "根據圖 16 結果,顯示芐丙酮與尼古丁對蜂鳥吸食花蜜有不同的影響,試推論其影響並說明理由。(4分)(於答題卷作答)\n芐丙酮:對蜂鳥吸食花蜜的影響(勾選,1分)——「抑制蜂鳥吸食花蜜」或「吸引蜂鳥吸食花蜜」;說明理由(範例已給):只有芐丙酮者,花蜜剩餘較少。\n尼古丁:對蜂鳥吸食花蜜的影響(勾選,1分)——「抑制蜂鳥吸食花蜜」或「吸引蜂鳥吸食花蜜」;說明理由(2分)。",
