        "passageTitle": "第44-46題題組",
        "passage": "在 2023 年,諾貝爾化學獎頒給從事奈米級量子點研究的三位學者。量子點是直徑介於 1 至 10 奈米的奈米粒子,由於其微小尺寸,可表現出獨特的性質。量子點的合成,可藉由添加不同界面活性劑等方法,來控制其大小及成分。硫化鋅量子點的合成實驗步驟如下:\n步驟 1. 配製甲與乙兩溶液,其組成如下:\n甲:0.25 M 半胱胺酸(胺基酸的一種)+ 0.125 M ZnSO₄\n乙:0.125 M Na₂S\n步驟 2. 將甲和乙溶液混合後,於 47°C 反應 60 分鐘,然後使用 1 M 醋酸鈉溶液,調整 pH 值至 6。\n步驟 3. 將冰冷乙醇逐滴加入,直至生成含有 ZnS 的白色沉澱物(稱為乙醇沉澱)。\n步驟 4. 經過 10 分鐘的離心後,取出沉澱物重新懸浮於水溶液中。\n步驟 5. 為去除大部分未反應的成分,需要進行至少兩次以上 3~4 步驟。\n表 8 顯示不同比例反應物及所得產物的鋅離子、硫離子含量及量子點的產率。\n表8\n樣品 | ZnSO₄(10⁻⁶莫耳) | Na₂S(10⁻⁶莫耳) | 半胱胺酸(10⁻⁶莫耳) | Zn²⁺(10⁻⁶莫耳) | S²⁻(10⁻⁶莫耳) | 量子點的產率(%)\n1 | 200 | 50 | 400 | 7.2 | 9.4 | 18.1\n2 | 200 | 100 | 400 | 37.6 | 46.5 | 44.7\n3 | 200 | 150 | 400 | 62.4 | 69.3 | 44.4\n4 | 200 | 200 | 400 | 88.0 | 88.0 | 44.0\n5 | 200 | 300 | 400 | 93.6 | 108.8 | 45.5\n6 | 200 | 400 | 400 | 104.6 | 117.0 | 50.2",
